//! Continuous effects ([CR 611](https://yawgatog.com/resources/magic-rules/#R611)) that
//! change a rule of the game
//! ([CR 613.11](https://yawgatog.com/resources/magic-rules/#R61311)).

use beryl_engine::TurnStep;
use beryl_scenario::{Action, Assertion, P0, P1, Permanent, Scenario};

use crate::{names, props};

const TEFERI: &str = names::TEFERI_TIME_RAVELER;

/// A rule changed by a resolving ability is changed at once and for the player it names
/// ([CR 611.2a](https://yawgatog.com/resources/magic-rules/#R6112a)): "A continuous effect
/// generated by the resolution of a spell or ability lasts as long as stated by the spell or
/// ability creating it". In the same turn's beginning of combat, no main phase, its
/// controller casts a sorcery.
pub const SCENARIOS: &[Scenario] =
    &[
        Scenario::new("A rule changed by an effect is changed in the turn it resolves")
            .battlefield(P0, &[Permanent::new(TEFERI), Permanent::new(names::PLAINS)])
            .hand(P0, &[props::SORCERY])
            .battlefield(P1, &[Permanent::new(props::CREATURE)])
            .library(P0, &[names::ISLAND, names::ISLAND])
            .library(P1, &[names::PLAINS, names::ISLAND])
            .actions(&[
                Action::activate(P0, TEFERI, 1),
                Action::Resolve,
                Action::AdvanceTo {
                    turn: 1,
                    step: TurnStep::BeginningOfCombat,
                },
                Action::cast(P0, props::SORCERY),
                // Second from the top: its owner has drawn the Plains above it since.
                Action::assert(Assertion::Library {
                    player: P1,
                    top: &[props::CREATURE, names::ISLAND],
                }),
                Action::assert(Assertion::Life {
                    player: P1,
                    life: 23,
                }),
            ]),
    ];
